import os
from moler.exceptions import CommandFailure  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.db_stats.ue.rtg import RTGStats  # type: ignore
from taf.ul.sc.perf.db_stats.ue.cus import CUSStats  # type: ignore
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore


def get_uesim_type(log_dir):
    unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
    ue_type = None
    report_location = os.path.join(log_dir, "report")
    try:
        ls_output = unix_local.ls(options="{} | grep -E 'RTG|CUS|IPHY'".format(report_location))
        ue_type = list(ls_output['files'].keys())[0]
    except (CommandFailure, KeyError) as error:
        MolerTest.warning(msg="UE report doesn't exist. Skipping parsing report...")
        MolerTest.warning(msg=error)
    return ue_type


class UEStats(object):
    def __new__(cls, log_dir, *args, **kwargs):
        ue_type = get_uesim_type(log_dir)
        ue_post_obj = None
        if ue_type == 'RTG':
            ue_post_obj = RTGStats
        elif ue_type == 'CUS':
            ue_post_obj = CUSStats

        if ue_post_obj:
            instance = super(UEStats, cls).__new__(ue_post_obj)

            if hasattr(cls, '__init__'):
                instance.__init__(log_dir, *args, **kwargs)

            return instance
